in:bottom center}.bar{position:absolute;bottom:0;width:100%;height:var(--h);background:var(--color);transform:translateZ(calc(var(--h)/2));box-shadow:inset -5px 0 rgba(0,0,0,.12),inset 0 -5px rgba(0,0,0,.1);transform-style:preserve-3d;transition:height .55s cubic-bezier(.2,.7,.1,1),filter .2s,opacity .2s}.bar:before,.bar:after{content:"";position:absolute;background:inherit}.bar:before{width:18px;height:18px;top:-9px;transform:rotateX(90deg);filter:brightness(1.22)}.bar:after{width:18px;height:100%;right:-9px;transform:rotateY(90deg);filter:brightness(.78)}.bar-wrap:hover .bar,.bar-wrap.selected .bar{filter:saturate(1.35) brightness(1.08);outline:2px solid var(--ink)}.bar-wrap.provisional .bar{background:repeating-linear-gradient(45deg,var(--orange) 0 7px,#ffd09d 7px 13px);border:1px dashed var(--ink)}.year-tag{position:absolute;bottom:-31px;left:50%;transform:translateX(-50%) rotateZ(26deg) rotateX(-57deg);font-size:10px;font-weight:800}.event-dot{position:absolute;left:50%;top:-18px;width:8px;height:8px;border-radius:50%;background:var(--red);transform:translateX(-50%);box-shadow:0 0 0 5px rgba(212,59,38,.16)}.trend-line{position:absolute;height:5px;background:var(--green);transform-origin:left center;opacity:.8;box-shadow:0 0 0 1px #fff;pointer-events:none}.trend-line:after{content:"TREND";position:absolute;right:-2px;top:-22px;font-size:9px;font-weight:900;color:var(--green);transform:rotateZ(26deg) rotateX(-57deg)}
.panel{border-left:1px solid var(--ink);padding:24px 22px;background:var(--paper);display:flex;flex-direction:column}.selected-kicker{text-transform:uppercase;letter-spacing:.16em;font-size:.68rem;font-weight:900;color:var(--orange)}.selected-year{font-family:Georgia,serif;font-size:4.3rem;line-height:1;margin:8px 0}.selected-temp{font-size:2rem;font-weight:900}.status{display:inline-block;margin:10px 0 19px;padding:5px 8px;background:var(--green);color:white;font-size:.62rem;text-transform:uppercase;letter-spacing:.12em;font-weight:900;align-self:flex-start}.status.provisional{background:var(--orange);color:var(--ink)}.months{border-top:1px solid var(--line)}.month{display:grid;grid-template-columns:1fr auto;gap:10px;padding:10px 0;border-bottom:1px solid var(--line);font-size:.84rem}.month b{color:var(--green)}.event-card{margin-top:20px;padding:15px;background:var(--ink);color:var(--paper)}.event-card small{color:var(--lime);text-transform:uppercase;letter-spacing:.14em;font-weight:800}.event-card h3{font-family:Georgia,serif;font-weight:400;font-size:1.35rem;margin:8px 0}.event-card p{font-size:.8rem;line-height:1.45;margin:0}.range{margin-top:auto;padding-top:22px}.range label{display:flex;justify-content:space-between;text-transform:uppercase;font-size:.65rem;font-weight:900;letter-spacing:.1em}.range input{width:100%;accent-color:var(--orange)}.hint{font-size:.69rem;color:var(--muted);line-height:1.4;margin-top:10px}
.legend{display:flex;flex-wrap:wrap;gap:18px;padding:12px 18px;border-top:1px solid var(--ink);font-size:.66rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800}.legend span{display:flex;align-items:center;gap:7px}.swatch{width:14px;height:14px;background:var(--green)}.swatch.hot{background:var(--orange)}.swatch.proj{background:repeating-linear-gradient(45deg,var(--orange) 0 4px,#ffd09d 4px 8px);border:1px dashed var(--ink)}.dot{width:8px;height:8px;border-radius:50%;background:var(--red)}
