.tooltip{position:fixed;z-index:20;pointer-events:none;background:var(--ink);color:white;padding:8px 10px;font-size:.73rem;opacity:0;transform:translate(12px,12px);transition:opacity .12s}.tooltip.show{opacity:1}
@media(max-width:880px){.hero{grid-template-columns:1fr}.hero-stat{display:none}.scene-wrap{grid-template-columns:1fr}.panel{border-left:0;border-top:1px solid var(--ink);display:grid;grid-template-columns:1fr 1fr;gap:12px}.range{grid-column:1/-1;margin:0}.viewport{min-height:510px}.scene{transform:rotateX(58deg) rotateZ(-30deg) scale(.65)}.notes{grid-template-columns:1fr}.meta{display:none}}
@media(max-width:560px){header{padding:18px}.hero{padding:42px 18px 18px}h1{font-size:3.65rem}.dashboard{margin:15px 10px 45px}.toolbar{align-items:flex-start}.action-group button:not(#playBtn){display:none}.viewport{min-height:430px}.scene{transform:rotateX(61deg) rotateZ(-34deg) scale(.48)}.panel{grid-template-columns:1fr}.range{grid-column:auto}.selected-year{font-size:3rem}.notes{padding:0 18px 50px}.legend{gap:10px}}
