<body>
<div class="noise"></div>
<header><div class="brand">PARIS<i>°</i> / SUMMER</div><div class="meta">Interactive climate study<br>1986 — 2026 · 48.86°N</div></header>
<section class="hero"><div><div class="eyebrow">Four decades of warmer summers</div><h1>Paris is<br>turning <em>up.</em></h1><p class="intro">Tilt, drag, and travel through forty-one summers. Each column represents the mean June–August air temperature over Paris; height and color reveal a clear long-term rise and increasingly frequent heat extremes.</p></div><div class="hero-stat"><strong id="trendStat">+0.0°C</strong><span>change in fitted trend, 1986–2025</span></div></section>
<main class="dashboard">
<div class="toolbar"><div class="mode-group"><button class="active" data-mode="temperature">Temperature</button><button data-mode="anomaly">Anomaly</button><button data-mode="events">Heat events</button></div><div class="action-group"><button id="resetBtn">Reset view</button><button id="playBtn">▶ Play timeline</button></div></div>
<div class="scene-wrap"><div class="viewport" id="viewport"><div class="sky-label">Summer mean temperature, °C</div><div class="scene" id="scene"><div class="floor" id="floor"></div><div class="bars" id="bars"></div></div></div>
<aside class="panel"><div><div class="selected-kicker">Selected summer</div><div class="selected-year" id="selectedYear">2026</div><div class="selected-temp" id="selectedTemp">21.0°C</div><span class="status provisional" id="status">Provisional scenario</span></div><div class="months" id="months"></div><div class="event-card" id="eventCard"><small>2026 status</small><h3>Summer still in progress</h3><p>The striped column is an illustrative provisional value, not a completed observation. It is kept separate from the historical trend calculation.</p></div><div class="range"><label><span>Travel through time</span><span id="rangeYear">2026</span></label><input id="yearRange" type="range" min="1986" max="2026" value="2026" step="1"><div class="hint">Drag the chart to rotate. Scroll to zoom. Select a bar or use arrow keys to inspect a year.</div></div></aside></div>
<div class="legend"><span><i class="swatch"></i> cooler summer</span><span><i class="swatch hot"></i> hotter summer</span><span><i class="swatch proj"></i> 2026 provisional</span><span><i class="dot"></i> notable heat event</span></div>
</main>
<section class="notes"><h2>A rising baseline makes exceptional heat more likely.</h2><div><p>The 3D ridge is not a weather forecast: it is a visual record of summer means. Individual years still jump up and down, but the fitted trend rises across the observed period.</p><p class="source"><strong>Data:</strong> NASA POWER MERRA-2 monthly mean 2 m air temperature at central Paris coordinates, June–August averages, 1986–2025. <strong>2026:</strong> illustrative provisional scenario (21.0°C), excluded from trend and historical statistics because the summer is incomplete as of 11 July 2026.</p></div></section>
<div class="tooltip" id="tooltip"></div>
<script>
const historical = __DATA__;
const data=[...historical,{year:2026,summer:21.0,june:null,july:null,august:null,provisional:true}];
const events={2003:{title:'The landmark 2003 heatwave',text:'A prolonged European heatwave made 2003 a defining public-health climate event.'},2019:{title:'Paris reaches 42.6°C',text:'Paris-Montsouris recorded its all-time high on 25 July 2019.'},2022:{title:'Repeated heat episodes',text:'A very warm, dry summer brought several heatwaves across France.'},2025:{title:'Another very warm summer',text:'The series remains elevated, close to the hottest recent summer means.'},2026:{title:'Summer still in progress',text:'The striped column is an illustrative provisional value, not a completed observation. It is kept separate from the historical trend calculation.'}};
const baseline=historical.filter(d=>d.year>=1991&&d.year<=2020).reduce((s,d)=>s+d.summer,0)/30;
const mean=historical.reduce((s,d)=>s+d.summer,0)/historical.length;
function regression(rows){const n=rows.length,sx=rows.reduce((s,d)=>s+d.year,0),sy=rows.reduce((s,d)=>s+d.summer,0),sxy=rows.reduce((s,d)=>s+d.year*d.summer,0),sx2=rows.reduce((s,d)=>s+d.year*d.year,0);const slope=(n*sxy-sx*sy)/(n*sx2-sx*sx);return{slope,intercept:(sy-slope*sx)/n}}
const reg=regression(historical);document.getElementById('trendStat').textContent=`+${(reg.slope*39).toFixed(1)}°C`;
const bars=document.getElementById('bars'), floor=document.getElementById('floor'), scene=document.getElementById('scene'), viewport=document.getElementById('viewport');
let selected=2026,mode='temperature',rotX=57,rotZ=-26,scale=innerWidth<560?.48:innerWidth<880?.65:.89,playing=false,timer;
const minT=15.5,maxT=21.5;
function colorFor(v){const t=Math.max(0,Math.min(1,(v-minT)/(maxT-minT)));const hue=145-(t*128);return `hsl(${hue} 67% ${42+t*10}%)`}
function heightFor(d){if(mode==='anomaly') return Math.max(20,105+(d.summer-baseline)*50);return 50+(d.summer-minT)*48}
function render(){bars.innerHTML='';floor.querySelectorAll('.axis-label').forEach(n=>n.remove());data.forEach((d,i)=>{const wrap=document.createElement('div');wrap.className=`bar-wrap${d.provisional?' provisional':''}${d.year===selected?' selected':''}`;wrap.style.left=`${18+i*23.7}px`;const bar=document.createElement('div');bar.className='bar';bar.style.setProperty('--h',`${heightFor(d)}px`);bar.style.setProperty('--color',colorFor(d.summer));bar.dataset.year=d.year;if(events[d.year]){const dot=document.createElement('i');dot.className='event-dot';bar.appendChild(dot)}const tag=document.createElement('span');tag.className='year-tag';tag.textContent=(d.year%5===0||d.year===1986||d.year===2026)?d.year:'';wrap.append(bar,tag);bars.appendChild(wrap);wrap.addEventListener('click',()=>selectYear(d.year));wrap.addEventListener('mousemove',e=>showTip(e,d));wrap.addEventListener('mouseleave',hideTip)});drawTrend();}
function drawTrend(){document.querySelectorAll('.trend-line').forEach(n=>n.remove());if(mode==='events')return;for(let i=0;i<historical.length-1;i++){const d=historical[i],next=historical[i+1],x1=27+i*23.7,y1=367-heightFor({...d,summer:reg.slope*d.year+reg.intercept}),x2=27+(i+1)*23.7,y2=367-heightFor({...next,summer:reg.slope*next.year+reg.intercept});const line=document.createElement('div');line.className='trend-line';const len=Math.hypot(x2-x1,y2-y1),ang=Math.atan2(y2-y1,x2-x1)*180/Math.PI;line.style.cssText=`left:${x1}px;top:${y1}px;width:${len}px;transform:rotate(${ang}deg) translateZ(12px)`;bars.appendChild(line)}}
function selectYear(year){selected=year;const d=data.find(x=>x.year===year);document.getElementById('selectedYear').textContent=year;document.getElementById('selectedTemp').textContent=mode==='anomaly'?`${d.summer-baseline>=0?'+':''}${(d.summer-baseline).toFixed(1)}°C`:`${d.summer.toFixed(1)}°C`;const status=document.getElementById('status');status.textContent=d.provisional?'Provisional scenario':'Observed / reanalysis';status.className=`status${d.provisional?' provisional':''}`;document.getElementById('rangeYear').textContent=year;document.getElementById('yearRange').value=year;document.querySelectorAll('.bar-wrap').forEach((n,i)=>n.classList.toggle('selected',data[i].year===year));document.getElementById('months').innerHTML=d.provisional?'<div class="month"><span>June–August</span><b>Incomplete</b></div><div class="month"><span>Scenario value</span><b>21.0°C</b></div>':[['June',d.june],['July',d.july],['August',d.august]].map(m=>`<div class="month"><span>${m[0]}</span><b>${Number(m[1]).toFixed(1)}°C</b></div>`).join('');const ev=events[year];document.getElementById('eventCard').innerHTML=ev?`<small>${year===2026?'2026 status':'Notable heat event'}</small><h3>${ev.title}</h3><p>${ev.text}</p>`:`<small>Year context</small><h3>${d.summer>mean?'Warmer':'Cooler'} than the 1986–2025 mean</h3><p>This summer was ${Math.abs(d.summer-mean).toFixed(1)}°C ${d.summer>mean?'above':'below'} the full-period mean in this dataset.</p>`;}
function showTip(e,d){const tip=document.getElementById('tooltip');tip.innerHTML=`<b>${d.year}</b> · ${d.summer.toFixed(1)}°C${d.provisional?'<br>provisional scenario':''}`;tip.style.left=e.clientX+'px';tip.style.top=e.clientY+'px';tip.classList.add('show')}function hideTip(){document.getElementById('tooltip').classList.remove('show')}
function updateScene(){scene.style.transform=`rotateX(${rotX}deg) rotateZ(${rotZ}deg) scale(${scale})`}
let dragging=false,lastX=0,lastY=0;viewport.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging')});viewport.addEventListener('pointermove',e=>{if(!dragging)return;rotZ+=(e.clientX-lastX)*.18;rotX=Math.max(35,Math.min(74,rotX-(e.clientY-lastY)*.12));lastX=e.clientX;lastY=e.clientY;updateScene()});viewport.addEventListener('pointerup',()=>{dragging=false;viewport.classList.remove('dragging')});viewport.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(.35,Math.min(1.3,scale-e.deltaY*.0007));updateScene()},{passive:false});
document.getElementById('yearRange').addEventListener('input',e=>selectYear(+e.target.value));document.querySelectorAll('[data-mode]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-mode]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');mode=btn.dataset.mode;render();selectYear(selected);if(mode==='events'){const first=2003;selectYear(first)}}));document.getElementById('resetBtn').addEventListener('click',()=>{rotX=57;rotZ=-26;scale=innerWidth<560?.48:innerWidth<880?.65:.89;updateScene()});document.getElementById('playBtn').addEventListener('click',e=>{playing=!playing;e.target.textContent=playing?'Ⅱ Pause timeline':'▶ Play timeline';clearInterval(timer);if(playing){if(selected===2026)selected=1985;timer=setInterval(()=>{selectYear(selected>=2026?1986:selected+1)},620)}});document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')selectYear(Math.min(2026,selected+1));if(e.key==='ArrowLeft')selectYear(Math.max(1986,selected-1))});window.addEventListener('resize',()=>{if(innerWidth<560)scale=.48;else if(innerWidth<880)scale=.65;updateScene()});render();selectYear(2026);updateScene();
</script>
</body></html>
